// Draft policy text, visible in demo and add-on. Owner must confirm business facts before publishing.
const policyTerms=`
<section id="sh-term-scope"><h3>1. Giới thiệu và phạm vi áp dụng</h3><p>SportHub V3 là nền tảng giới thiệu và mua sắm sản phẩm thể thao, đồng thời hỗ trợ tính năng kế hoạch luyện tập cá nhân. Điều khoản này áp dụng cho người truy cập, đăng ký tài khoản và sử dụng các tính năng được SportHub cung cấp.</p><p><strong>Đây là bản dự thảo nội dung chính sách để duyệt.</strong> Trước khi áp dụng cho website kinh doanh thật, chủ website cần cập nhật tên chủ thể kinh doanh, địa chỉ, phương thức hỗ trợ và chính sách bán hàng cụ thể.</p></section>
<section id="sh-term-account"><h3>2. Tài khoản thành viên</h3><ul><li>SportHub chỉ mở một loại tài khoản đăng ký công khai: <strong>Khách hàng/Thành viên</strong>. Tạo tài khoản không đồng nghĩa được cấp quyền quản trị.</li><li>Bạn cung cấp họ tên và email chính xác; số điện thoại là tùy chọn khi đăng ký, nhưng có thể cần để xử lý giao hàng.</li><li>Mỗi người dùng cần bảo vệ mật khẩu, không sử dụng tài khoản người khác và thông báo cho SportHub khi nghi ngờ truy cập trái phép.</li><li>Việc tạo tài khoản và sử dụng dịch vụ phải phù hợp với độ tuổi, năng lực hành vi và quy định pháp luật có liên quan. Người chưa thành niên cần sự hỗ trợ/đồng ý phù hợp từ người đại diện hợp pháp.</li></ul></section>
<section id="sh-term-orders"><h3>3. Sản phẩm, giá và đặt hàng</h3><ul><li>Thông tin tên, hình ảnh, màu sắc, kích cỡ, giá và tình trạng hàng sẽ được hiển thị theo dữ liệu SportHub cập nhật. Hình minh họa có thể khác sản phẩm thực tế trong giới hạn đã công bố.</li><li>Trước khi xác nhận, người mua cần được xem tổng tiền, phí vận chuyển (nếu có), phương thức thanh toán, địa chỉ nhận hàng và thông tin liên quan.</li><li>Việc gửi yêu cầu đặt hàng không mặc nhiên bảo đảm có hàng; tình trạng xác nhận/hủy đơn phải được thông báo minh bạch theo quy trình bán hàng thực tế.</li><li>Mọi chương trình khuyến mãi phải có thời hạn, điều kiện áp dụng rõ ràng; trường hợp hiển thị sai cần thông báo, xử lý phù hợp với quyền lợi người tiêu dùng.</li></ul></section>
<section id="sh-term-fulfill"><h3>4. Thanh toán, giao hàng, đổi trả và bảo hành</h3><p>Chính sách thanh toán, đơn vị vận chuyển, khu vực giao hàng, phí vận chuyển, thời gian dự kiến, cách hủy/đổi/trả hàng và bảo hành phải được công bố riêng ở trang bán hàng trước khi khách thanh toán. SportHub không tự đặt ra một mức phí hay thời hạn đổi trả chung trong bản demo này.</p><p>Trong trường hợp quyền của người mua theo pháp luật cao hơn nội dung mô tả tại website, quy định pháp luật có liên quan được ưu tiên áp dụng.</p></section>
<section id="sh-term-plan"><h3>5. Kế hoạch luyện tập cá nhân</h3><p>Gợi ý luyện tập và dinh dưỡng của SportHub là thông tin tham khảo, <strong>không thay thế tư vấn của bác sĩ, chuyên gia y tế hoặc chuyên gia dinh dưỡng</strong>. Người dùng nên lựa chọn bài tập phù hợp thể trạng, dừng tập khi có dấu hiệu bất thường và tìm hỗ trợ chuyên môn khi cần.</p><p>Nếu tính năng tương lai yêu cầu số đo cơ thể, mục tiêu sức khỏe hay thông tin nhạy cảm, SportHub phải giải thích cụ thể dữ liệu cần thu thập và có cơ chế đồng ý phù hợp trước khi xử lý.</p></section>
<section id="sh-term-conduct"><h3>6. Hành vi bị cấm và quyền sở hữu nội dung</h3><ul><li>Không giả mạo thông tin, gian lận ưu đãi, xâm nhập trái phép hệ thống, phát tán mã độc hoặc khai thác trái phép dữ liệu người dùng khác.</li><li>Không sao chép thương hiệu, hình ảnh, mã nguồn hoặc nội dung thuộc quyền sở hữu của SportHub/đối tác ngoài phạm vi được cho phép.</li><li>SportHub có thể hạn chế hoặc tạm khóa truy cập khi có căn cứ cho thấy hành vi vi phạm; việc xử lý phải hợp lý và không làm mất các quyền hợp pháp của khách hàng.</li></ul></section>
<section id="sh-term-change"><h3>7. Cập nhật, gián đoạn và giải quyết phản ánh</h3><p>SportHub có thể cập nhật tính năng, biểu giá và chính sách, nhưng cần thông báo rõ thay đổi có ảnh hưởng đáng kể trước khi áp dụng. Website có thể tạm gián đoạn vì bảo trì hoặc sự cố; SportHub có trách nhiệm xử lý và thông tin phù hợp.</p><p>Khách hàng có thể gửi yêu cầu hỗ trợ về tài khoản, đơn hàng, sản phẩm hoặc khiếu nại qua <a href="mailto:tranthiquynhnhu0901@gmail.com">tranthiquynhnhu0901@gmail.com</a>. Việc giải quyết tranh chấp tuân theo pháp luật Việt Nam và các cơ chế bảo vệ người tiêu dùng có liên quan.</p></section>
<section id="sh-term-effective"><h3>8. Hiệu lực và liên hệ</h3><p><strong>Phiên bản dự thảo:</strong> 23/10/2026. Điều khoản chỉ có hiệu lực chính thức khi chủ website công bố trên SportHub V3 và hoàn tất thông tin doanh nghiệp/hộ kinh doanh, địa chỉ và kênh hỗ trợ. Không có nội dung nào trong điều khoản này loại bỏ các quyền người tiêu dùng theo pháp luật.</p></section>`;
const policyPrivacy=`
<section id="sh-privacy-owner"><h3>1. Đơn vị vận hành và phạm vi chính sách</h3><p>SportHub V3 dự kiến quản lý dữ liệu phát sinh khi khách truy cập website, tạo tài khoản, đặt hàng, sử dụng kế hoạch cá nhân hoặc liên hệ hỗ trợ. Email liên hệ đề xuất: <a href="mailto:tranthiquynhnhu0901@gmail.com">tranthiquynhnhu0901@gmail.com</a>.</p><p><strong>Thông tin cần hoàn thiện trước khi triển khai thực tế:</strong> tên đầy đủ của chủ thể xử lý dữ liệu, địa chỉ giao dịch, số điện thoại hỗ trợ và các nhà cung cấp hạ tầng đang thực sự sử dụng.</p></section>
<section id="sh-privacy-data"><h3>2. Các loại dữ liệu được thu thập</h3><ul><li><strong>Thông tin tài khoản:</strong> họ tên, email và số điện thoại nếu bạn cung cấp; ngày đăng ký, trạng thái xác minh và lựa chọn nhận tin.</li><li><strong>Thông tin đơn hàng khi được tích hợp:</strong> sản phẩm, số lượng, người nhận, địa chỉ giao hàng, thanh toán và trạng thái đơn. Không thu thập thông tin thẻ thanh toán trên trang tĩnh khi chưa có cổng thanh toán đạt yêu cầu.</li><li><strong>Thông tin kế hoạch cá nhân:</strong> mục tiêu tập luyện và những dữ liệu bạn chủ động nhập. Nếu có số đo, tình trạng sức khỏe hoặc dữ liệu nhạy cảm, cần thông báo cụ thể và xin sự đồng ý phù hợp trước khi xử lý.</li><li><strong>Dữ liệu kỹ thuật:</strong> nhật ký truy cập, thiết bị, trình duyệt, cookie hoặc vùng lưu trữ phiên cần thiết để vận hành đăng nhập và bảo vệ hệ thống.</li><li><strong>Thông tin chăm sóc khách hàng:</strong> lịch sử liên hệ, yêu cầu hỗ trợ, nhãn CRM và ghi chú liên quan đến việc phục vụ khách hàng.</li></ul><p><strong>Mật khẩu:</strong> trong mô hình triển khai bằng Supabase, mật khẩu được xử lý qua hệ thống xác thực; SportHub không đưa mật khẩu thô vào CRM hoặc email gửi quản trị viên.</p></section>
<section id="sh-privacy-purpose"><h3>3. Mục đích và cơ sở xử lý</h3><ul><li>Tạo, xác thực và bảo vệ tài khoản; lưu cài đặt và duy trì phiên đăng nhập.</li><li>Tiếp nhận yêu cầu đặt hàng, cung cấp dịch vụ, vận chuyển, hỗ trợ sau bán và thực hiện các nghĩa vụ có liên quan.</li><li>Lưu tiến độ kế hoạch cá nhân khi người dùng lựa chọn sử dụng.</li><li>Phòng ngừa gian lận, bảo vệ an toàn website và xử lý yêu cầu từ cơ quan có thẩm quyền khi pháp luật yêu cầu.</li><li>Gửi thông tin quảng cáo và ưu đãi <strong>chỉ khi người dùng chủ động đánh dấu đồng ý nhận tin</strong>; không ép chọn ô này để đăng ký.</li></ul><p>Thông báo và việc xin đồng ý cần được thiết kế phù hợp với từng mục đích xử lý, nhất là với thông tin nhạy cảm.</p></section>
<section id="sh-privacy-share"><h3>4. Người được tiếp cận và đối tác xử lý</h3><p>Chỉ nhân sự/quản trị được phân quyền mới được truy cập CRM theo nhu cầu công việc. Khi tích hợp thật, dữ liệu có thể được xử lý bởi nhà cung cấp xác thực và cơ sở dữ liệu (dự kiến Supabase), Google OAuth nếu bạn lựa chọn đăng nhập Google, dịch vụ gửi email (dự kiến Resend), và đối tác vận chuyển/thanh toán nếu phát sinh đơn hàng thực.</p><p>Không bán danh sách khách hàng cho bên thứ ba. Việc chia sẻ cho nhà cung cấp hoặc cơ quan có thẩm quyền chỉ thực hiện trong phạm vi cần thiết và phù hợp pháp luật. Nếu hạ tầng đặt ngoài Việt Nam, SportHub phải rà soát các nghĩa vụ liên quan đến xử lý/chuyển dữ liệu xuyên biên giới trước khi sử dụng.</p></section>
<section id="sh-privacy-retain"><h3>5. Thời hạn lưu trữ và nguyên tắc xóa</h3><p>SportHub dự kiến duy trì dữ liệu tài khoản trong thời gian tài khoản hoạt động; dữ liệu đơn hàng và chứng từ theo thời hạn pháp luật yêu cầu; dữ liệu tiếp thị cho đến khi bạn rút lại đồng ý hoặc mục đích xử lý kết thúc; dữ liệu kỹ thuật chỉ trong thời gian cần thiết cho vận hành và bảo mật.</p><p><strong>Trước khi phát hành thật,</strong> chủ website cần xác định và công bố thời hạn hoặc tiêu chí xóa cụ thể cho từng loại dữ liệu, lịch sao lưu và cách xử lý dữ liệu trong bản sao lưu. Khi nhận yêu cầu xóa hợp lệ, dữ liệu sẽ được xử lý theo quy định pháp luật, trừ phần bắt buộc phải lưu giữ.</p></section>
<section id="sh-privacy-rights"><h3>6. Quyền và lựa chọn của bạn</h3><p>Bạn có thể yêu cầu: được biết về hoạt động xử lý; truy cập và nhận thông tin; sửa thông tin chưa chính xác; rút lại sự đồng ý; phản đối hoặc yêu cầu hạn chế xử lý; yêu cầu xóa dữ liệu theo điều kiện pháp luật; khiếu nại khi thấy việc xử lý không phù hợp.</p><p>Gửi yêu cầu từ email dùng để đăng ký đến <a href="mailto:tranthiquynhnhu0901@gmail.com">tranthiquynhnhu0901@gmail.com</a>. SportHub có thể cần xác minh người yêu cầu trước khi cung cấp hoặc thay đổi dữ liệu và phải phản hồi theo thời hạn pháp luật áp dụng. Rút lại đồng ý tiếp thị không làm mất khả năng sử dụng tài khoản.</p></section>
<section id="sh-privacy-security"><h3>7. Biện pháp bảo mật</h3><p>Khi vận hành thật, SportHub dự kiến sử dụng HTTPS, xác thực tài khoản, kiểm tra quyền truy cập ở cơ sở dữ liệu, giới hạn quyền quản trị và giữ các khóa API bí mật ngoài mã GitHub Pages. Không đưa danh sách khách hàng hay file CRM chứa dữ liệu thật lên kho GitHub công khai.</p><p>Không hệ thống nào bảo đảm an toàn tuyệt đối. Khi phát hiện nguy cơ lộ lọt dữ liệu, SportHub cần đánh giá, khắc phục và thực hiện nghĩa vụ thông báo theo quy định áp dụng.</p></section>
<section id="sh-privacy-device"><h3>8. Cookie, dữ liệu phiên và bản demo</h3><p>Website sử dụng thông tin phiên trên trình duyệt để duy trì trạng thái đăng nhập khi tích hợp dịch vụ xác thực. <code>sessionStorage</code> chỉ được dùng để ghi nhận bạn đã xem lời mời đăng ký trong phiên hiện tại. Đăng nhập và dữ liệu CRM cần kết nối Supabase để vận hành; chúng tôi không lưu mật khẩu trong CRM.</p><p>Trước khi vận hành chính thức, chủ website cần rà soát cách lưu trữ phiên, cookie và mọi công cụ phân tích được sử dụng; bổ sung thông báo phù hợp nếu cần.</p></section>
<section id="sh-privacy-minor"><h3>9. Trẻ em, thay đổi chính sách và liên hệ</h3><p>Việc xử lý dữ liệu của trẻ em cần cơ chế bảo vệ và sự đồng ý phù hợp từ người có thẩm quyền theo quy định pháp luật. SportHub sẽ thông báo khi có thay đổi quan trọng trong cách thu thập hoặc sử dụng dữ liệu.</p><p><strong>Phiên bản dự thảo:</strong> 23/10/2026. Liên hệ bảo vệ dữ liệu: <a href="mailto:tranthiquynhnhu0901@gmail.com">tranthiquynhnhu0901@gmail.com</a>.</p></section>`;
function showPolicy(which){
 const privacy=which==='privacy';const title=privacy?'Chính sách quyền riêng tư':'Điều khoản sử dụng';
 // A second layer ensures that the partially completed registration form remains untouched.
 $('#sh-policy-place',root)?.remove();const layer=document.createElement('div');layer.id='sh-policy-place';layer.className='sh-policy-backdrop';
 const toc=privacy?[['Dữ liệu thu thập','#sh-privacy-data'],['Mục đích xử lý','#sh-privacy-purpose'],['Lưu trữ','#sh-privacy-retain'],['Quyền của bạn','#sh-privacy-rights']]:[['Tài khoản','#sh-term-account'],['Đặt hàng','#sh-term-orders'],['Đổi trả','#sh-term-fulfill'],['Kế hoạch cá nhân','#sh-term-plan']];
 layer.innerHTML=`<section class="sh-policy-panel" role="dialog" aria-modal="true" aria-labelledby="sh-policy-title" tabindex="-1"><header class="sh-policy-header"><span class="sh-top-label">SPORTHUB · QUY ĐỊNH MINH BẠCH</span><button type="button" class="sh-policy-x" aria-label="Đóng chính sách">×</button><h2 id="sh-policy-title">${title}</h2><p>Bản dự thảo cập nhật 23/10/2026 · Vui lòng đọc kỹ trước khi đồng ý tạo tài khoản.</p></header><nav class="sh-policy-toc" aria-label="Xem nhanh nội dung">${toc.map(([label,href])=>`<a href="${href}">${label}</a>`).join('')}</nav><article class="sh-policy-content">${privacy?policyPrivacy:policyTerms}</article><footer class="sh-policy-footer"><span>Thông tin minh bạch · Không bắt buộc đồng ý nhận quảng cáo</span><button class="sh-policy-return" type="button">← Quay lại đăng ký</button></footer></section>`;
 root.append(layer);const close=()=>{layer.remove();const target=activeModal?.querySelector('[data-sh-policy="'+which+'"]');target?.focus({preventScroll:true})};
 layer.querySelector('.sh-policy-x').onclick=close;layer.querySelector('.sh-policy-return').onclick=close;
 layer.addEventListener('click',e=>{if(e.target===layer)close()});
 layer.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}});
 layer.querySelector('.sh-policy-x').focus({preventScroll:true});
}

async function submitAuth(form){const btn=$('#sh-submit',form),email=form.elements.namedItem('email').value.trim().toLowerCase(),pass=form.elements.namedItem('password').value;const signup=authMode==='signup';
  if(!email||(DEMO?!email.length:!/^\S+@\S+\.\S+$/.test(email))){feedback('Vui lòng nhập '+(DEMO?'email hoặc số điện thoại':'địa chỉ email')+' hợp lệ.');return}
  if(pass.length<8){feedback('Mật khẩu phải có ít nhất 8 ký tự.');return}
  if(signup){if(!form.elements.namedItem('name').value.trim()){feedback('Vui lòng điền họ và tên.');return}if(form.elements.namedItem('confirm').value!==pass){feedback('Hai mật khẩu chưa trùng khớp.');return}if(!$('#sh-terms',form).checked){feedback('Bạn cần đồng ý với điều khoản và chính sách để đăng ký.');return}}
  btn.disabled=true;feedback('Đang xử lý...');try{
  if(DEMO){if(signup){if(demoData.customers.some(c=>c.email===email||c.phone===email))throw Error('Tài khoản này đã tồn tại trong bản mô phỏng.');let profile={id:uid(),full_name:form.elements.namedItem('name').value.trim(),email,phone:form.elements.namedItem('phone').value.trim(),account_type:'customer',company_name:'',source:'SportHub V3 / Demo',created_at:now(),marketing_consent:$('#sh-marketing',form).checked,stage:'Mới',tags:[],notes:''};demoData.customers.unshift(profile);demoData.events.unshift({title:'Đăng ký tài khoản mới (DEMO)',name:profile.full_name,email,time:now()});saveDemo();user={id:profile.id,email:profile.email,user_metadata:{full_name:profile.full_name}};}else{const p=demoData.customers.find(c=>c.email===email||c.phone===email);if(!p)throw Error('Chưa có hồ sơ mô phỏng này. Hãy đăng ký trước.');user={id:p.id,email:p.email,user_metadata:{full_name:p.full_name}};}
  } else {if(!sb)throw Error('Tài khoản chưa được kích hoạt. Quản trị viên cần cấu hình Supabase theo README.');if(signup){const {data,error}=await sb.auth.signUp({email,password:pass,options:{emailRedirectTo:location.origin+location.pathname,data:{full_name:form.elements.namedItem('name').value.trim(),phone:form.elements.namedItem('phone').value.trim(),account_type:'customer',company_name:'',marketing_consent:$('#sh-marketing',form).checked,terms_accepted_at:now(),source:'SportHub V3'}}});if(error)throw error;if(!data?.session){feedback('Đăng ký đã được tiếp nhận. Vui lòng kiểm tra email để xác nhận tài khoản.',true);return;}await refreshIdentity();}
    else{const {error}=await sb.auth.signInWithPassword({email,password:pass});if(error)throw error;await refreshIdentity();}}
  paintAccount();closeModal();toast(signup?'Đã tạo hồ sơ '+(DEMO?'DEMO':'thành công')+'!':'Đã đăng nhập '+(DEMO?'DEMO':'thành công')+'!');resumePending();
  }catch(e){feedback(e.message||'Có lỗi xảy ra, hãy thử lại.')}finally{btn.disabled=false}
}
async function googleLogin(){if(DEMO){feedback('Đây là giao diện mô phỏng. Đăng nhập Google thật sẽ hoạt động sau khi cấu hình Supabase và Google OAuth.');return}if(!sb){feedback('Chưa cấu hình Supabase');return}const {error}=await sb.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname}});if(error)feedback(error.message)}
async function forgotPassword(){if(DEMO){feedback('Chức năng đặt lại mật khẩu qua email chỉ hoạt động khi kết nối Supabase.');return}const val=$('#sh-email',activeModal)?.value?.trim();if(!val||!/^\S+@\S+\.\S+$/.test(val)){feedback('Nhập địa chỉ email hợp lệ phía trên trước.');return}if(!sb){feedback('Chức năng chưa kết nối Supabase.');return}const {error}=await sb.auth.resetPasswordForEmail(val,{redirectTo:location.origin+location.pathname});feedback(error?error.message:'Nếu địa chỉ email tồn tại, hướng dẫn khôi phục sẽ được gửi.',!error)}
function showResetPassword(){
 const content='<form id="sh-reset-form"><label for="sh-reset-pass" class="sh-label">Mật khẩu mới (tối thiểu 8 ký tự)</label><input id="sh-reset-pass" class="sh-field" type="password" minlength="8" autocomplete="new-password" required><label for="sh-reset-confirm" class="sh-label">Xác nhận mật khẩu mới</label><input id="sh-reset-confirm" class="sh-field" type="password" minlength="8" autocomplete="new-password" required><button type="submit" class="sh-primary">Cập nhật mật khẩu</button><p class="sh-feedback" id="sh-feedback" role="status"></p></form>';
 const w=modal('Đặt lại mật khẩu','Nhập mật khẩu mới để bảo vệ tài khoản của bạn.',content);
 $('#sh-reset-form',w).onsubmit=async e=>{e.preventDefault();const pw=$('#sh-reset-pass',w).value,check=$('#sh-reset-confirm',w).value;if(pw.length<8){feedback('Mật khẩu cần tối thiểu 8 ký tự.');return}if(pw!==check){feedback('Hai mật khẩu chưa trùng nhau.');return}if(!sb){feedback('Chưa kết nối Supabase.');return}const{error}=await sb.auth.updateUser({password:pw});if(error){feedback(error.message);return}closeModal();toast('Đã cập nhật mật khẩu thành công.');};
}
function paintAccount(){const b=$('#sh-account',root);b.textContent=user?'♙  '+(user.user_metadata?.full_name||user.email):'♙  Đăng nhập / Đăng ký';document.querySelectorAll('[data-open-account]').forEach(n=>{n.textContent=user?'Tài khoản của tôi':'Đăng nhập'});$('#sh-nudge-place',root).replaceChildren();renderToolbar()}
function showAccount(){const body=`<p style="font-size:14px">Đang sử dụng tài khoản: <b>${esc(user?.email||'')}</b></p>${DEMO?'<p class="sh-note">Dữ liệu đăng nhập hiện tại chỉ là mô phỏng trên trình duyệt.</p>':''}<button class="sh-primary" type="button" id="sh-logout">Đăng xuất</button>${admin||adminDemo?'<button class="sh-google" id="sh-opencrm">Mở quản trị CRM</button>':''}`;const w=modal('Thông tin tài khoản','Thông tin phiên hoạt động hiện tại',body);$('#sh-logout',w).onclick=async()=>{if(sb&&!DEMO)await sb.auth.signOut();user=null;admin=false;adminDemo=false;editMode=false;renderEditing();paintAccount();closeModal();toast('Đã đăng xuất');if(onProtectedPlan)openAuth('login')};$('#sh-opencrm',w)?.addEventListener('click',()=>openAdmin('crm'))}
function detectGate(el){if(!(el instanceof Element))return null;const marked=el.closest('[data-sh-auth]');if(marked)return marked;const b=el.closest('a,button,input[type="submit"],[role="button"]');if(!b||root.contains(b))return null;const name=((b.textContent||b.value||'')+' '+(b.getAttribute('aria-label')||'')).toLocaleLowerCase('vi');const href=(b.getAttribute('href')||'').toLowerCase();if(/đặt hàng|thanh toán|thanh toan|hoàn tất đơn|kế hoạch cá nhân|checkout|đặt mua/.test(name)||/checkout|thanh-toan/.test(href))return b;return null}
let bypass=null;
function interceptGate(ev){
  if(ev.button!==0||ev.ctrlKey||ev.metaKey||ev.altKey||ev.shiftKey||user)return;
  const el=detectGate(ev.target);if(!el||el===bypass)return;
  // Allow a real anchor to open V2. V2 itself verifies the login session,
  // so a returning member won't see a login/registration pop-up on V1.
  if(el.tagName==='A' && planUrl){try{
    const dest=new URL(el.href,location.href);
    if(dest.origin===planUrl.origin &&
       (dest.pathname.replace(/\/$/,'')===planPath || dest.pathname.startsWith(planPath+'/')))return;
  }catch{}}
  ev.preventDefault();ev.stopImmediatePropagation();pending=el;
  const isPlanAction=el.dataset.shAuth==='plan'||/kế hoạch cá nhân/i.test(el.textContent||'');
  openAuth(isPlanAction?'signup':'login');
}
function resumePending(){if(!pending)return;const el=pending;pending=null;if(!el.isConnected)return;bypass=el;el.click();queueMicrotask(()=>{bypass=null})}
function showPrompt(){if(user||onProtectedPlan)return;try{if(sessionStorage.getItem('sh_prompt_v3_seen'))return;sessionStorage.setItem('sh_prompt_v3_seen','yes')}catch{}const node=document.createElement('div');node.className='sh-nudge';node.innerHTML='<strong>🎁 Tham gia SportHub ngay!</strong><p>Tạo tài khoản miễn phí để dễ dàng đặt hàng, lưu kế hoạch cá nhân và nhận ưu đãi.</p><button type="button" class="sh-join">Đăng ký miễn phí</button><button class="sh-muted-btn" type="button">Để sau</button>';$('#sh-nudge-place',root).append(node);$('.sh-join',node).onclick=()=>{node.remove();openAuth('signup')};$('.sh-muted-btn',node).onclick=()=>node.remove()}
async function refreshIdentity(){if(DEMO||!sb)return;const {data,error}=await sb.auth.getUser();if(error)console.warn('[SportHub]',error.message);user=data?.user||null;admin=false;if(user&&user.email?.toLowerCase()===ADMIN&&user.email_confirmed_at){const {data:roleRow}=await sb.from('admins').select('user_id').eq('user_id',user.id).maybeSingle();admin=!!roleRow}paintAccount();
  if(onProtectedPlan){
    if(user){
      // On the first visit, this closes ONLY the loading overlay; after an OAuth
      // return, it also closes the auth form. No signup prompt for valid sessions.
      if(activeModal?.dataset.shGateLoading==='true'||activeModal?.querySelector('#sh-auth-form'))closeModal();
    }else if(!activeModal||activeModal.dataset.shGateLoading==='true')openAuth('signup');
  }
  if(user&&pending)resumePending()}
function enterDemoAdmin(){if(!DEMO)return;adminDemo=true;renderToolbar();openAdmin('overview');toast('Đây là quyền quản trị mô phỏng, không phải xác thực tài khoản thật.')}
function renderToolbar(){const slot=$('#sh-toolbar-place',root);slot.replaceChildren();if(!admin&&!adminDemo)return;const bar=document.createElement('div');bar.className='sh-toolbar';bar.innerHTML=`<strong>★ QUẢN TRỊ ${DEMO?'DEMO':'SPORTHUB'}</strong><button type="button" id="sh-manage">CRM / Quản lý</button><button type="button" class="sh-outline" id="sh-edit-mode">${editMode?'Tắt sửa nội dung':'Sửa trực tiếp'}</button>${DEMO?'<button type="button" class="sh-outline" id="sh-leave-preview">Thoát thử quản trị</button>':''}`;slot.append(bar);$('#sh-manage',bar).onclick=()=>openAdmin('overview');$('#sh-edit-mode',bar).onclick=()=>{editMode=!editMode;renderEditing();renderToolbar();toast(editMode?'Chạm vào phần được đánh dấu để sửa.':'Đã tắt chế độ chỉnh sửa.')};$('#sh-leave-preview',bar)?.addEventListener('click',()=>{adminDemo=false;editMode=false;renderEditing();renderToolbar()})}
function renderEditing(){$$('[data-sh-edit]').forEach(n=>n.classList.toggle('sh-editor-on',editMode&&(admin||adminDemo)))}
function handleEditClick(e){if(!(admin||adminDemo)||!editMode)return;const n=e.target instanceof Element?e.target.closest('[data-sh-edit]'):null;if(!n||root.contains(n))return;e.preventDefault();e.stopImmediatePropagation();openEditor(n)}
function applyContent(){for(const n of $$('[data-sh-edit]')){let key=n.dataset.shEdit;let item=DEMO?demoData.content[key]:content.get(key);if(!item)continue;if(n.tagName==='IMG'&&item.kind==='image'){if((/^https:\/\//.test(item.value)||DEMO&&/^data:image\/(png|jpeg|webp);base64,/.test(item.value))&&n.getAttribute('src')!==item.value)n.src=item.value}else if(item.kind==='text'&&n.textContent!==item.value)n.textContent=item.value}}
async function openEditor(node){const key=node.dataset.shEdit,kind=node.tagName==='IMG'?'image':'text',old=kind==='image'?(node.getAttribute('src')||''):node.textContent.trim();const body=`<form id="sh-content-form"><label class="sh-label">Khóa nội dung</label><div class="sh-note">${esc(key)}</div><label class="sh-label" for="sh-value">${kind==='image'?'URL ảnh HTTPS hoặc tải ảnh bên dưới':'Nội dung mới'}</label>${kind==='image'?`<input id="sh-value" class="sh-field" value="${esc(old)}"><label class="sh-label" for="sh-imagefile">Tải ảnh JPG / PNG / WebP (tối đa 3 MB)</label><input id="sh-imagefile" class="sh-field" type="file" accept="image/jpeg,image/png,image/webp">`:`<textarea class="sh-field" id="sh-value" maxlength="10000">${esc(old)}</textarea>`}<button type="submit" class="sh-primary">Lưu thay đổi</button><div id="sh-feedback" class="sh-feedback" role="status"></div></form>`;
 const w=modal(kind==='image'?'Thay ảnh trực tiếp':'Chỉnh sửa nội dung','Chỉ cập nhật đúng mục bạn chọn, không làm thay đổi giao diện xung quanh.',body);
 $('#sh-content-form',w).onsubmit=async e=>{e.preventDefault();let val=$('#sh-value',w).value.trim();const f=$('#sh-imagefile',w)?.files?.[0];try{if(f){if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>3e6)throw Error('Chỉ nhận JPG/PNG/WebP không quá 3 MB.');if(DEMO){val=await compressImage(f)}else{const ext={'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[f.type],path=`${user.id}/${uid()}.${ext}`;const {error}=await sb.storage.from('site-images').upload(path,f,{upsert:false});if(error)throw error;val=sb.storage.from('site-images').getPublicUrl(path).data.publicUrl;}}
 if(!val)throw Error('Nội dung không được để trống.');if(kind==='image'&&!(/^https:\/\//.test(val)||DEMO&&/^data:image\//.test(val)))throw Error('Chỉ chấp nhận ảnh từ URL HTTPS.');if(val.length>15000)throw Error('Nội dung quá dài.');if(DEMO){demoData.content[key]={kind,value:val};saveDemo()}else{const {error}=await sb.from('site_content').upsert({key,kind,value:val,updated_by:user.id,updated_at:now()},{onConflict:'key'});if(error)throw error;content.set(key,{kind,value:val})}
 applyContent();closeModal();toast('Đã lưu thay đổi '+(DEMO?'mô phỏng':'thành công'));
 }catch(err){feedback(err.message)}};
}
async function compressImage(file){const bitmap=await createImageBitmap(file),c=document.createElement('canvas');const scale=Math.min(1,680/Math.max(bitmap.width,bitmap.height));c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close?.();return c.toDataURL('image/webp',.72)}
async function loadCRM(){if(DEMO)return demoData.customers;const getAll=async(tbl,cols,order)=>{let out=[];for(let n=0;n<100000;n+=500){let query=sb.from(tbl).select(cols).range(n,n+499);if(order)query=query.order(order,{ascending:false});const {data,error}=await query;if(error)throw error;out.push(...data);if(data.length<500)break;}return out};const [profiles,detail]=await Promise.all([getAll('profiles','id,full_name,email,phone,account_type,company_name,source,created_at,marketing_consent,terms_accepted_at','created_at'),getAll('crm_details','user_id,stage,tags,notes,updated_at')]);let map=new Map(detail.map(d=>[d.user_id,d]));return profiles.map(x=>({...x,...(map.get(x.id)||{}),stage:map.get(x.id)?.stage||'Mới',tags:map.get(x.id)?.tags||[],notes:map.get(x.id)?.notes||''}))}
